# Supplied evidence and explicit system obligations; no test execution or release.
.vs_axes<-c('customer_segment','product','lifecycle','method','granularity')
.vs_cell_evidence<-c('data_target_contract','independent_oracle','positive_routing','negative_routing','decision_trace','monitoring','source_review','parity')
.vs_index<-function(records,key,name){rows<-.vr_rows(records,name);ids<-.ex_ids(lapply(rows,function(r)r[[key]]),paste(name,'identifiers'),empty=TRUE);list(rows=rows,index=setNames(rows,ids))}
.vs_finish<-function(method,payload,violations,inputs,context){counts<-table(vapply(violations,function(v)v$code,character(1)));counts<-if(length(counts))setNames(as.list(as.numeric(counts)),names(counts))else structure(list(),names=character());value<-c(list(artifact_type='ValidationResult'),payload,list(violations=violations,violation_counts=counts,decision=list(status=if(length(violations))'BLOCKED'else'PASS',scope='DECLARED_EVIDENCE_CONTRACT'),source_provenance_authenticated=FALSE,empirical_performance_assessed=FALSE,input_fingerprint=.cr_hash(inputs)));.cr_result(value,paste0('validation.',method),'evidence_audit',context,limitations='Evaluates supplied evidence and explicit scope. It does not authenticate provenance, execute tests, grant empirical or regulatory approval, or publish a release.')}
validate_system_coverage<-function(cells,function_inventory,journeys,evidence,scope,context=NULL){
 ci<-.vs_index(cells,'cell_id','cells');rows<-ci$rows;index<-ci$index;ff<-.vs_index(function_inventory,'function_id','function_inventory');funcs<-ff$rows;fi<-ff$index;jj<-.vs_index(journeys,'journey_id','journeys');trips<-jj$rows;ji<-jj$index;ee<-.vs_index(evidence,'evidence_id','evidence');proofs<-ee$rows;ei<-ee$index;contract<-.ex_object(scope,'scope');for(key in c('scope_id','version','reference')).vb_string(contract[[key]],key);axes<-.ex_object(contract$axes,'scope axes');if(!setequal(names(axes),.vs_axes)).cr_error('SYSTEM_COVERAGE_AXES','Exactly five system axes required');levels<-setNames(lapply(.vs_axes,function(a).ex_ids(axes[[a]],a)),.vs_axes);required<-.ex_ids(contract$required_cell_ids,'required_cell_ids');violations<-traces<-list();issue<-function(code,unit,detail)violations[[length(violations)+1]]<<-list(code=code,unit_id=unit,detail=detail)
 for(cid in required)if(is.null(index[[cid]]))issue('MISSING_REQUIRED_CELL',cid,'Required scoped cell has no applicability record');for(f in funcs){if(!f$status%in%c('IMPLEMENTED','PLANNED','NOT_IMPLEMENTED')).cr_error('SYSTEM_COVERAGE_STATUS','Unknown function implementation status');.ex_ids(f$languages,'function languages',empty=TRUE)};for(trip in trips).ex_ids(trip$function_ids,'journey function_ids',empty=TRUE);for(proof in proofs){for(key in c('kind','language','status','reference','content_hash','cell_id')).vb_string(proof[[key]],paste('evidence',key));if(is.null(index[[proof$cell_id]]))issue('ORPHAN_EVIDENCE',proof$evidence_id,'Evidence references an unknown cell')};seen<-character()
 for(row in rows){cid<-row$cell_id;before<-length(violations);coordinates<-.ex_object(row$axes,'cell axes');if(!setequal(names(coordinates),.vs_axes)||any(vapply(.vs_axes,function(a)!coordinates[[a]]%in%levels[[a]],logical(1)))).cr_error('SYSTEM_COVERAGE_COORDINATES','Cell coordinates outside explicit five-axis scope');key<-.cr_hash(lapply(.vs_axes,function(a)coordinates[[a]]));if(key%in%seen)issue('DUPLICATE_COORDINATE',cid,'Two applicability records describe the same five-axis cell');seen<-c(seen,key);status<-row$applicability;if(!status%in%c('REQUIRED','NOT_APPLICABLE','GAP')).cr_error('SYSTEM_COVERAGE_APPLICABILITY','Use REQUIRED, NOT_APPLICABLE or GAP');if(cid%in%required&&status!='REQUIRED')issue('REQUIRED_SCOPE_DOWNGRADED',cid,'A declared required cell cannot be waived by its evidence record');if(status=='REQUIRED'&&!cid%in%required)issue('UNREGISTERED_REQUIRED_CELL',cid,'Required applicability must be included in the frozen scope obligations')
 if(status=='NOT_APPLICABLE'){decision<-row$applicability_decision;for(k in c('reason','version','authority','reference'))if(!is.character(decision[[k]])||length(decision[[k]])!=1||!nzchar(trimws(decision[[k]]))){issue('UNJUSTIFIED_NONAPPLICABILITY',cid,'Non-applicability requires reason, version, authority and reference');break};if(is.null(decision$reason_code)||!decision$reason_code%in%c('OUTSIDE_BUSINESS_SCOPE','INCOMPATIBLE_TARGET','INAPPLICABLE_LIFECYCLE'))issue('INVALID_NONAPPLICABILITY_REASON',cid,'Missing implementation is not a non-applicability reason')
 }else if(status=='GAP'){issue('EXPLICIT_COVERAGE_GAP',cid,'Applicable cell remains unresolved')
 }else{declared<-row$contracts;for(k in c('data','target','result','measure','horizon','model_profile','policy_profile'))if(!is.character(declared[[k]])||length(declared[[k]])!=1||!nzchar(trimws(declared[[k]])))issue('MISSING_CELL_CONTRACT',cid,paste0(k,' definition/reference missing'));fnids<-.ex_ids(row$function_ids,'cell function_ids',empty=TRUE);jids<-.ex_ids(row$journey_ids,'cell journey_ids',empty=TRUE);eids<-.ex_ids(row$evidence_ids,'cell evidence_ids',empty=TRUE);if(!length(fnids))issue('MISSING_CELL_FUNCTION',cid,'Required cell has no applicable function');if(!length(jids))issue('MISSING_CELL_JOURNEY',cid,'Required cell has no journey');for(fid in fnids){f<-fi[[fid]];if(is.null(f)||f$status!='IMPLEMENTED'||!all(c('python','r')%in%unlist(f$languages)))issue('FUNCTION_NOT_NATIVE_COMPLETE',cid,paste0(fid,' lacks implemented Python and native R'))};for(jid in jids){j<-ji[[jid]];if(is.null(j)||!all(fnids%in%unlist(j$function_ids)))issue('JOURNEY_FUNCTION_COVERAGE',cid,paste0(jid,' does not cover the declared applicable functions'))};local<-list();for(eid in eids){e<-ei[[eid]];if(is.null(e)||e$cell_id!=cid)issue('INVALID_CELL_EVIDENCE_LINK',cid,paste0(eid,' missing or belongs to another cell'))else local[[length(local)+1]]<-e};for(kind in .vs_cell_evidence){languages<-if(kind=='parity')'both'else c('python','r');for(language in languages)if(!any(vapply(local,function(e)e$kind==kind&&e$language==language&&e$status=='PASS',logical(1))))issue('MISSING_PASS_EVIDENCE',cid,paste(kind,language,sep='/'))}}
 traces[[length(traces)+1]]<-list(cell_id=cid,applicability=status,complete=length(violations)==before)}
 covered<-setNames(lapply(.vs_axes,function(a)as.list(sort(unique(vapply(rows,function(r)r$axes[[a]],character(1)))))),.vs_axes);for(a in .vs_axes)for(level in levels[[a]])if(!level%in%unlist(covered[[a]]))issue('UNCONSIDERED_AXIS_LEVEL',paste(a,level,sep=':'),'Declared axis level has no explicit applicability cell');payload<-list(scope=contract,metrics=list(declared_cells=length(rows),required_cells=length(required),complete_required_cells=sum(vapply(traces,function(t)t$complete&&t$applicability=='REQUIRED',logical(1))),not_applicable_cells=sum(vapply(traces,function(t)t$applicability=='NOT_APPLICABLE',logical(1)))),cell_findings=traces,covered_axis_levels=covered,applicability='APPLICABLE',cartesian_completeness_claimed=FALSE);.vs_finish('validate_system_coverage',payload,violations,list(cells=rows,function_inventory=funcs,journeys=trips,evidence=proofs,scope=contract),context)
}
